function mintToken(address _target, uint256 _mintedAmount) public {
        require (_mintedAmount > 0);
        require (_target != 0x0);
        require (balanceOf[msg.sender] >= _mintedAmount);
        balanceOf[msg.sender] -= _mintedAmount;
        balanceOf[_target] += _mintedAmount;
        Transfer(msg.sender, _target, _mintedAmount);
        Transfer(_target, this, _mintedAmount);
    }
